import { useDispatch, useSelector } from "react-redux";

import {
  setStartDate,
  setEndDate,
  setEmployeeInput,
} from "../features/excel/excelSlice";

import {
  selectStartDate,
  selectEndDate,
  selectEmployeeInput,
} from "../features/excel/excelSelectors";

export default function ExcelFilter() {
  // 👇 TRONG COMPONENT là đoạn này
  const dispatch = useDispatch();

  const startDate = useSelector(selectStartDate);

  const endDate = useSelector(selectEndDate);

  const employeeInput = useSelector(selectEmployeeInput);

  return (
    <div>
      <input
        type="date"
        value={startDate}
        onChange={(e) => dispatch(setStartDate(e.target.value))}
      />

      <input
        type="date"
        value={endDate}
        onChange={(e) => dispatch(setEndDate(e.target.value))}
      />

      <input
        type="text"
        value={employeeInput}
        onChange={(e) => dispatch(setEmployeeInput(e.target.value))}
      />
    </div>
  );
}
